import React, { HTMLProps, PropsWithChildren, useMemo } from 'react';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';

import { useScroll } from '../../hooks/useScroll.js';

type GradientProps = {
  sizeStart: number;
  sizeEnd: number;
  color: string;
  horizontal: boolean;
};

const Gradient = /* @__PURE__ */ styled('div')<GradientProps>((props) => ({
  position: 'relative',
  width: '100%',
  height: '100%',

  '&::after': {
    pointerEvents: 'none',
    position: 'absolute',
    inset: 0,
    content: '""',
    background: `linear-gradient(
      ${props.horizontal ? '90deg' : '180deg'},
      ${props.color} 0%,
      rgba(255, 255, 255, 0) ${props.sizeStart}px,
      rgba(255, 255, 255, 0) calc(100% - ${props.sizeEnd}px),
      ${props.color} 100%
    )`,
  },
}));

export type ScrollGradientProps = HTMLProps<HTMLDivElement> & {
  contentElement: HTMLElement | null | undefined;
  size?: number;
  orientation?: 'horizontal' | 'vertical';
  color?: string;
};

export const ScrollGradient = ({
  contentElement,
  size = 24,
  orientation = 'vertical',
  color = Colors.Background.Base.Default,
  children,
}: PropsWithChildren<ScrollGradientProps>) => {
  const scroll = useScroll(contentElement, orientation === 'horizontal');

  const [sizeStart, sizeEnd] = useMemo(
    () => [
      scroll.scrollable ? Math.min(size, scroll.start) : 0,
      scroll.scrollable ? Math.min(size, scroll.max - scroll.end) : 0,
    ],
    [scroll.end, scroll.max, scroll.scrollable, scroll.start, size],
  );

  return (
    <Gradient
      color={color}
      sizeStart={sizeStart}
      sizeEnd={sizeEnd}
      horizontal={orientation === 'horizontal'}
    >
      {children}
    </Gradient>
  );
};

ScrollGradient['displayName'] = 'ScrollGradient';
